using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_API_KEY");
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

        return new AzureOpenAIClient(new Uri(endpoint), new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();
    }

    /// <summary>
    /// Creates a chat client with OpenTelemetry tracing wired up (telemetry mode).
    /// </summary>
    public static IChatClient CreateTelemetryClient()
    {
        // Wire OTel tracing for AI calls
        Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddConsoleExporter()
            .Build();

        return new ChatClientBuilder(CreateChatClient())
            .UseOpenTelemetry()
            .Build();
    }

    /// <summary>
    /// Returns the chat client used as the evaluator judge for quality scoring.
    /// </summary>
    public static IChatClient CreateJudgeClient() => CreateChatClient();

    /// <summary>
    /// Quality evaluators: relevance, coherence, fluency, groundedness.
    /// </summary>
    public static IList<IEvaluator> QualityEvaluators() =>
    [
        new RelevanceEvaluator(),
        new CoherenceEvaluator(),
        new FluencyEvaluator(),
        new GroundednessEvaluator(),
    ];

    /// <summary>
    /// Creates a reporting configuration that persists eval results for comparison.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(string scenarioName)
    {
        var storageDir = Path.Combine(
            AppContext.BaseDirectory, ".eval-results", scenarioName);

        return new ReportingConfiguration(
            storageRootPath: storageDir,
            evaluators: QualityEvaluators(),
            chatConfiguration: new ChatConfiguration(CreateJudgeClient()));
    }
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: verifies that AI calls produce trace spans via OpenTelemetry.
/// </summary>
[TestClass]
public class TelemetryEvalTests
{
    [TestMethod]
    public async Task ChatCompletion_EmitsTraceSpan()
    {
        var client = EvalConfig.CreateTelemetryClient();

        var response = await client.GetResponseAsync("Say hello in one word.");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Length > 0, "Expected a non-empty response.");
