using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: scores responses on relevance, coherence, fluency, groundedness.
/// </summary>
[TestClass]
public class QualityEvalTests
{
    private static readonly ReportingConfiguration s_config =
        EvalConfig.CreateReportingConfig("quality");

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync(
            "CoachResponse_MeetsQualityBar");

        var client = scenario.ChatConfiguration!.ChatClient;
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my focus while working remotely?"),
        };

        var response = await client.GetResponseAsync(messages);
        messages.AddRange(response.ToChatMessages());

        await scenario.EvaluateAsync(messages, response);

        // Assert quality scores meet a minimum threshold
        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result is NumericMetric metric)
            {
                Assert.IsTrue(
                    metric.Value >= 3,
                    $"{metric.Identifier.DisplayName} scored {metric.Value}, expected >= 3");
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_FollowUp_StaysCoherent()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync(
            "CoachResponse_FollowUp_StaysCoherent");

        var client = scenario.ChatConfiguration!.ChatClient;
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "Give me a morning routine for productivity."),
        };

        var first = await client.GetResponseAsync(messages);
        messages.AddRange(first.ToChatMessages());

        messages.Add(new ChatMessage(ChatRole.User, "Can you make it shorter, under 5 steps?"));
        var response = await client.GetResponseAsync(messages);
        messages.AddRange(response.ToChatMessages());

        await scenario.EvaluateAsync(messages, response);

        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result is NumericMetric metric)
            {
                Assert.IsTrue(
                    metric.Value >= 3,
                    $"{metric.Identifier.DisplayName} scored {metric.Value}, expected >= 3");
            }
        }
    }
}

