    public async Task Compare_SystemPromptVariants()
    {
        var question = "What are three ways to manage stress at work?";

        foreach (var (prompt, index) in s_systemPrompts.Select((p, i) => (p, i)))
        {
            var variantName = $"variant_{index}";
            var config = EvalConfig.CreateReportingConfig($"compare/{variantName}");

            await using var scenario = await config.CreateScenarioRunAsync(
                "Compare_SystemPromptVariants");

            var client = scenario.ChatConfiguration!.ChatClient;
            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, prompt),
                new(ChatRole.User, question),
            };

            var response = await client.GetResponseAsync(messages);
            messages.AddRange(response.ToChatMessages());

            await scenario.EvaluateAsync(messages, response);
        }
    }
}

